 <div class="hint"><kbd>WASD</kbd> mover &nbsp; <kbd>E</kbd> entrar/sair do carro<br><kbd>SHIFT</kbd> acelerar &nbsp; <kbd>ESPAÇO</kbd> buzina</div>
 <div class="touchControls"><div class="joystick" id="joy"><div class="stick" id="stick"></div></div><div class="touchButtons"><button class="touchBtn" id="boost">TURBO</button><button class="touchBtn primary" id="action">ENTRAR</button></div></div>
 <div class="toast" id="toast"></div><div class="rotate">Gire o aparelho para uma experiência melhor.<br>O jogo funciona em qualquer orientação.</div>
 <script>
+(()=>{'use strict';
+const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
+let W=0,H=0,DPR=1,S=24,camX=0,camZ=0,last=0,toastTimer=0,cash=0,got=0,beep=0;
+const player={x:0,z:0,car:false,angle:0,vx:0,vz:0};
+const keys=new Set(),joy={x:0,y:0,active:false};
+const pickups=[{x:12,z:-18},{x:-18,z:-12},{x:18,z:12},{x:-12,z:20}].map(p=>({...p,taken:false,phase:Math.random()*7}));
+const buildings=[],trees=[],cars=[];
+let seed=4127;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
+function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';S=Math.min(W/30,H/19,30);S=Math.max(12,S)}
+addEventListener('resize',resize);resize();
+const roads=[-25,-15,-5,5,15,25];
+// Hand-built blocks: compact towers and pastel homes frame a generous, drivable street grid.
+for(let ix=0;ix<5;ix++)for(let iz=0;iz<5;iz++){
+ const cx=-20+ix*10,cz=-20+iz*10;
+ if(ix===2&&iz===2)continue;
+ const n=2+Math.floor(rand()*3);
+ for(let j=0;j<n;j++){
+  const w=2.4+rand()*2.2,d=2.3+rand()*2.2;
+  const x=cx+(rand()-.5)*4.3,z=cz+(rand()-.5)*4.3;
+  let h=2+rand()*6;if(rand()>.74)h+=2.5;
+  const palette=['#d9aa7f','#dfd1b3','#96aaa2','#d7c6a9','#a3b6b3','#c68d78','#e6d9c2','#829995'];
+  buildings.push({x,z,w,d,h,color:palette[Math.floor(rand()*palette.length)],roof:['#748682','#947e67','#657773','#b79e7b'][Math.floor(rand()*4)],seed:rand()});
+ }
+}
+for(let i=0;i<38;i++){const x=(rand()-.5)*58,z=(rand()-.5)*58;if(Math.min(...roads.map(r=>Math.abs(x-r)),...roads.map(r=>Math.abs(z-r)))>2.1)trees.push({x,z,h:1.6+rand()*.9,phase:rand()})}
+for(let i=0;i<9;i++)cars.push({x:-24+rand()*48,z:-24+rand()*48,a:rand()*Math.PI*2,color:['#e4ad55','#d85f4e','#3c8b96','#dfe1d5','#554e73'][i%5]});
+function project(x,z,y=0){return {x:W*.5+(x-camX-z+camZ)*.8660254*S,y:H*.51+(x-camX+z-camZ)*.5*S-y*S}}
+function poly(points,fill,stroke=null,lw=1){ctx.beginPath();points.forEach((p,i)=>{const q=project(p[0],p[1],p[2]||0);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
+function line(a,b,color,width){const p=project(a[0],a[1],a[2]||0),q=project(b[0],b[1],b[2]||0);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke()}
+function cube(b){const {x,z,w,d,h,color,roof}=b,x0=x-w/2,x1=x+w/2,z0=z-d/2,z1=z+d/2;
+ // floating afternoon shadow
+ poly([[x0+.38,z0+.35,0],[x1+.65,z0+.35,0],[x1+.65,z1+.65,0],[x0+.38,z1+.65,0]],'#17251f30');
+ // two sunlit facades and rooftop
+ poly([[x1,z0,0],[x1,z1,0],[x1,z1,h],[x1,z0,h]],shade(color,-.19));
+ poly([[x0,z1,0],[x1,z1,0],[x1,z1,h],[x0,z1,h]],shade(color,-.07));
+ poly([[x0,z0,h],[x1,z0,h],[x1,z1,h],[x0,z1,h]],roof);
+ // neat, warm glass windows on both visible walls
+ const cols=Math.max(1,Math.floor(w/1.05)),rows=Math.max(1,Math.floor(h/1.12));
+ for(let c=0;c<cols;c++)for(let r=0;r<rows;r++){
+  const wx=x0+(c+.5)*w/cols,wz=z0+(c+.5)*d/cols,wy=.55+(r+.5)*(h-.45)/rows;
+  poly([[x1,z0+(c+.33)*d/cols,wy-.22],[x1,z0+(c+.68)*d/cols,wy-.22],[x1,z0+(c+.68)*d/cols,wy+.18],[x1,z0+(c+.33)*d/cols,wy+.18]],windowColor(b.seed,r,c));
+  poly([[x0+(c+.33)*w/cols,z1,wy-.22],[x0+(c+.68)*w/cols,z1,wy-.22],[x0+(c+.68)*w/cols,z1,wy+.18],[x0+(c+.33)*w/cols,z1,wy+.18]],windowColor(b.seed,r,c+1));
+ }
+}
+function shade(hex,amt){let n=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(n>>16)+255*amt)),g=Math.max(0,Math.min(255,((n>>8)&255)+255*amt)),b=Math.max(0,Math.min(255,(n&255)+255*amt));return `rgb(${r|0},${g|0},${b|0})`}
+function windowColor(s,r,c){return (r*3+c*7+s*11)%6<2?'#f8d993':'#526e6b'}

