function windowColor(s,r,c){return (r*3+c*7+s*11)%6<2?'#f8d993':'#526e6b'}
function drawGround(){
 const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#83a896');g.addColorStop(.55,'#789b88');g.addColorStop(1,'#557b71');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // subtle patchwork park blocks, then asphalt streets
 for(const x of roads)for(const z of roads){poly([[x-4.2,z-4.2],[x+4.2,z-4.2],[x+4.2,z+4.2],[x-4.2,z+4.2]],(Math.round(x+z)%3===0?'#84a890':'#7d9f89'))}
 for(const a of roads){poly([[-32,a-1.6],[32,a-1.6],[32,a+1.6],[-32,a+1.6]],'#434f4d');poly([[a-1.6,-32],[a+1.6,-32],[a+1.6,32],[a-1.6,32]],'#434f4d');
  // pale curbs
  line([-32,a-1.56,0],[32,a-1.56,0],'#d2c9a7',1.4);line([a-1.56,-32,0],[a-1.56,32,0],'#d2c9a7',1.4);
 }
 // lane dashes, in both directions
 for(const a of roads)for(let t=-30;t<30;t+=5){line([t,a,0],[t+2,a,0],'#d9d0ad88',1.5);line([a,t,0],[a,t+2,0],'#d9d0ad88',1.5)}
 // scenic waterfront promenade at the southern edge
 poly([[-32,30],[-26,30],[-26,32],[-32,32]],'#64a9a9');line([-32,29.8,0],[-26,29.8,0],'#e1ddc2',2);
}
function palm(t){const base=project(t.x,t.z),tip=project(t.x,t.z,t.h);ctx.strokeStyle='#665746';ctx.lineWidth=Math.max(2,S*.1);ctx.beginPath();ctx.moveTo(base.x,base.y);ctx.lineTo(tip.x,tip.y);ctx.stroke();
 for(let k=0;k<6;k++){const a=k*Math.PI/3+t.phase;ctx.beginPath();ctx.moveTo(tip.x,tip.y);ctx.quadraticCurveTo(tip.x+Math.cos(a)*S*.35,tip.y+Math.sin(a)*S*.17,tip.x+Math.cos(a)*S*.72,tip.y+Math.sin(a)*S*.31);ctx.strokeStyle=k%2?'#416b50':'#527e58';ctx.lineWidth=Math.max(2,S*.13);ctx.stroke()}
}
function drawCar(x,z,angle,color,scale=1){
 const fw=1.12*scale,sw=.57*scale;
 function pos(a,b,h=0){return [x+Math.cos(angle)*a-Math.sin(angle)*b,z+Math.sin(angle)*a+Math.cos(angle)*b,h]}
 // tires, chassis, canopy
 poly([pos(-fw,-sw,.09),pos(fw,-sw,.09),pos(fw,sw,.09),pos(-fw,sw,.09)],'#26312f');
 poly([pos(-fw*.87,-sw*.82,.23),pos(fw*.88,-sw*.82,.23),pos(fw*.88,sw*.82,.23),pos(-fw*.87,sw*.82,.23)],color);
 poly([pos(-.38,-sw*.66,.53),pos(.44,-sw*.66,.53),pos(.44,sw*.66,.53),pos(-.38,sw*.66,.53)],'#b9d1c3');
 // windscreen on the nose and soft highlight
 poly([pos(.46,-sw*.61,.28),pos(fw*.76,-sw*.61,.24),pos(fw*.76,sw*.61,.24),pos(.46,sw*.61,.28)],'#d9dbbf');
 const p=project(x,z,.62);ctx.beginPath();ctx.arc(p.x,p.y,S*.29*scale,0,Math.PI*2);ctx.fillStyle='#fff5d5';ctx.fill();
}
function drawPickup(p,t){const bob=Math.sin(t*2.7+p.phase)*.12,pt=project(p.x,p.z,1.1+bob);ctx.save();ctx.translate(pt.x,pt.y);ctx.rotate(t+p.phase);ctx.shadowColor='#ffe07a';ctx.shadowBlur=18;ctx.fillStyle='#ffe07a';ctx.beginPath();ctx.moveTo(0,-S*.43);ctx.lineTo(S*.3,0);ctx.lineTo(0,S*.43);ctx.lineTo(-S*.3,0);ctx.closePath();ctx.fill();ctx.restore();const foot=project(p.x,p.z,0);ctx.beginPath();ctx.ellipse(foot.x,foot.y,S*.48,S*.2,0,0,Math.PI*2);ctx.fillStyle='#ffe07a33';ctx.fill()}
function drawPlayer(){if(player.car)return;const p=project(player.x,player.z,.3);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#15211e55';ctx.beginPath();ctx.ellipse(0,S*.18,S*.25,S*.12,0,0,7);ctx.fill();ctx.fillStyle='#e7bb72';ctx.beginPath();ctx.arc(0,-S*.16,S*.17,0,7);ctx.fill();ctx.fillStyle='#e96f4d';ctx.beginPath();ctx.ellipse(0,S*.08,S*.19,S*.29,0,0,7);ctx.fill();ctx.strokeStyle='#dfbf94';ctx.lineWidth=S*.07;ctx.beginPath();ctx.moveTo(-S*.12,S*.1);ctx.lineTo(-S*.22,S*.35);ctx.moveTo(S*.12,S*.1);ctx.lineTo(S*.22,S*.35);ctx.stroke();ctx.restore()}
function drawMinimap(){const size=Math.min(110,W*.24),x=W-size-20,y=H*.5-size/2;ctx.save();ctx.globalAlpha=.91;ctx.fillStyle='#152321d9';ctx.beginPath();ctx.roundRect(x,y,size,size,12);ctx.fill();ctx.save();ctx.beginPath();ctx.roundRect(x+5,y+5,size-10,size-10,9);ctx.clip();ctx.translate(x+size/2,y+size/2);const k=size/66;ctx.scale(k,k);ctx.translate(-camX,-camZ);ctx.fillStyle='#718f7e';ctx.fillRect(-32,-32,64,64);ctx.fillStyle='#515b58';roads.forEach(r=>{ctx.fillRect(-32,r-1.5,64,3);ctx.fillRect(r-1.5,-32,3,64)});buildings.forEach(b=>{ctx.fillStyle='#b9aa8b';ctx.fillRect(b.x-b.w/2,b.z-b.d/2,b.w,b.d)});pickups.filter(p=>!p.taken).forEach(p=>{ctx.fillStyle='#ffe07a';ctx.beginPath();ctx.arc(p.x,p.z,1.2,0,7);ctx.fill()});ctx.fillStyle='#ec7650';ctx.beginPath();ctx.arc(player.x,player.z,1.8,0,7);ctx.fill();ctx.restore();ctx.strokeStyle='#ffffff25';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(x,y,size,size,12);ctx.stroke();ctx.restore()}
function render(t){ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);drawGround();
 const items=[];buildings.forEach(b=>items.push({d:b.x+b.z+.01,type:'b',o:b}));trees.forEach(o=>items.push({d:o.x+o.z,type:'t',o}));cars.forEach(o=>items.push({d:o.x+o.z,type:'c',o}));pickups.filter(p=>!p.taken).forEach(o=>items.push({d:o.x+o.z+.02,type:'p',o}));items.push({d:player.x+player.z+.03,type:'player'});items.sort((a,b)=>a.d-b.d);
 for(const q of items){if(q.type==='b')cube(q.o);else if(q.type==='t')palm(q.o);else if(q.type==='c')drawCar(q.o.x,q.o.z,q.o.a,q.o.color,.85);else if(q.type==='p')drawPickup(q.o,t);else if(player.car)drawCar(player.x,player.z,player.angle,'#e96f4d');else drawPlayer()}
 // warm evening bloom
 const vg=ctx.createRadialGradient(W*.53,H*.42,Math.min(W,H)*.18,W*.53,H*.42,Math.max(W,H)*.72);vg.addColorStop(0,'#ffe8bd09');vg.addColorStop(1,'#07121948');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);drawMinimap();
}

