 // warm evening bloom
 const vg=ctx.createRadialGradient(W*.53,H*.42,Math.min(W,H)*.18,W*.53,H*.42,Math.max(W,H)*.72);vg.addColorStop(0,'#ffe8bd09');vg.addColorStop(1,'#07121948');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H);drawMinimap();
}
let ownCar={x:2,z:0};
function blocked(x,z){if(Math.abs(x)>30||Math.abs(z)>30)return true;return buildings.some(b=>Math.abs(x-b.x)<b.w/2+.38&&Math.abs(z-b.z)<b.d/2+.38)}
function move(dx,dz){const nx=player.x+dx,nz=player.z+dz;if(!blocked(nx,player.z))player.x=nx;if(!blocked(player.x,nz))player.z=nz}
function showToast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function toggleCar(){
